glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv;
out vec4 color;
vec4 vert () { uv=a_texCoord; color=a_color; return cc_matViewProj*vec4(a_position,1.0); }
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec2 uv;
in vec4 color;
layout(std140) uniform FlowParams { vec4 params; vec4 bounds; vec4 detail; };
uniform sampler2D maskTex;
vec4 over(vec4 a,vec4 b){return vec4(b.rgb*b.a+a.rgb*(1.0-b.a),b.a+a.a*(1.0-b.a));}
float radial(vec2 p,vec2 c,float r){float d=length(p-c)/r;return d<.30?mix(1.0,.42,d/.30):mix(.42,0.0,clamp((d-.30)/.70,0.0,1.0));}
float radialPosition(vec2 p,vec2 f,vec2 c,float r){vec2 q=p-f,d=c-f;float A=dot(d,d)-r*r,B=-2.0*dot(q,d),C=dot(q,q);return clamp((-B-sqrt(max(0.0,B*B-4.0*A*C)))/(2.0*A),0.0,1.0);}
vec4 band(float u){
  if(u<0.0||u>1.0)return vec4(0.0);
  vec4 a=vec4(114,55,228,0),b=vec4(163,92,255,.30),c=vec4(209,168,255,.72),d=vec4(250,235,255,1),e=vec4(161,85,255,.35);
  vec4 v=u<.24?mix(a,b,u/.24):u<.45?mix(b,c,(u-.24)/.21):u<.52?mix(c,d,(u-.45)/.07):u<.67?mix(d,e,(u-.52)/.15):mix(e,a,(u-.67)/.33);v.rgb/=255.0;return v;
}
vec4 frag () {
  vec2 p=uv*vec2(384,768);float time=params.x,kind=params.z,grade=params.w;vec4 col=vec4(0.0);
  if(kind<1.5){
    if(grade<25.0){float rate=grade<20.0?.26:.34;float cy=bounds.x+bounds.y*(1.0-fract(time*rate))-13.0;float span=grade<20.0?13.0:17.0;col=over(col,band((p.y-cy-.05*(p.x-192.0)+span)/(2.0*span)));}
    else {for(int i=0;i<3;i++){float waves=grade>29.0?3.0:2.0;if(float(i)>=waves)break;float y=453.0-fract(time*.35+float(i)/waves)*360.0;col=over(col,vec4(vec3(246,206,255)/255.0,radial(p,vec2(192,y),43.0)*.95));}}
  } else if(kind<2.5){float cy=bounds.x+bounds.y*(1.0-fract(time*.20+.32));vec4 b=band((p.y-cy+.06*(p.x-192.0)+42.0)/84.0);b.a*=.42;col=over(col,b);}
  else if(kind<3.5){float y=485.0-fract(time*.6)*410.0;col=over(col,vec4(vec3(219,149,255)/255.0,radial(p,vec2(192,y),140.0)*.8));}
  else {
    if(grade<25.0){float u=radialPosition(p,vec2(bounds.z-detail.x*.15,bounds.w-detail.x*.2),bounds.zw,detail.x*1.2);vec4 a=vec4(255,241,255,.9),b=vec4(220,172,255,.8),c=vec4(155,67,255,.45),d=vec4(128,48,255,0);vec4 v=u<.22?mix(a,b,u/.22):u<.7?mix(b,c,(u-.22)/.48):mix(c,d,(u-.7)/.3);v.rgb/=255.0;col=over(col,v);}
    else {vec3 c=grade>29.0?vec3(252,225,255):vec3(247,213,255);col=over(col,vec4(c/255.0,radial(p,vec2(bounds.z-2.0,bounds.w-5.0),detail.x*1.9)));}
  }
  float alpha=texture(maskTex,uv).a*params.y*color.a;return vec4(clamp(col.rgb*alpha,0.0,1.0),clamp(col.a*alpha,0.0,1.0));
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

